+import type { AnyColumn } from '~/column.ts';
+import type { SQL, SQLWrapper } from '../sql.ts';
+import { sql } from '../sql.ts';
+
+type ValueOf<T extends SQLWrapper> = T extends AnyColumn ? T['_']['data'] : T extends SQL<infer TValue> ? TValue : unknown;
+
+type WindowValue<T> = SQL<T> & { over(spec?: WindowSpec | string): SQL<T> };
+
+export interface WindowSpec {
+	partitionBy?: SQLWrapper | SQLWrapper[];
+	orderBy?: SQLWrapper | SQLWrapper[];
+	frame?: WindowFrame;
+}
+
+export interface FrameBoundary extends SQLWrapper {
+	readonly position: number;
+}
+
+export interface WindowFrame extends SQLWrapper {}
+
+function boundary(value: string, position: number): FrameBoundary {
+	return { position, getSQL: () => sql.raw(value) };
+}
+
+export const unboundedPreceding = boundary('unbounded preceding', Number.NEGATIVE_INFINITY);
+export const currentRow = boundary('current row', 0);
+export const unboundedFollowing = boundary('unbounded following', Number.POSITIVE_INFINITY);
+
+function offsetBoundary(name: 'preceding' | 'following', value: number): FrameBoundary {
+	if (!Number.isInteger(value) || value < 0) {
+		throw new Error(`${name}() requires a non-negative integer; received ${value}`);
+	}
+	return boundary(`${value} ${name}`, name === 'preceding' ? -value : value);
+}
+
+export function preceding(value: number): FrameBoundary {
+	return offsetBoundary('preceding', value);
+}
+
+export function following(value: number): FrameBoundary {
+	return offsetBoundary('following', value);
+}
+
+function frame(kind: 'rows' | 'range', { from, to }: { from: FrameBoundary; to: FrameBoundary }): WindowFrame {
+	if (from.position > to.position) {
+		throw new Error('The frame "from" boundary must not be ordered after "to"');
+	}
+	return { getSQL: () => sql`${sql.raw(kind)} between ${from} and ${to}` };
+}
+
+export function rows(spec: { from: FrameBoundary; to: FrameBoundary }): WindowFrame {
+	return frame('rows', spec);
+}
+
+export function range(spec: { from: FrameBoundary; to: FrameBoundary }): WindowFrame {
+	return frame('range', spec);
+}
+
+function over<T>(expression: SQL<T>): WindowValue<T> {
+	return Object.assign(expression, {
+		over(spec: WindowSpec | string = {}): SQL<T> {
+			if (typeof spec === 'string') return sql`${expression} over ${sql.identifier(spec)}`;
+			const partitionBy = spec.partitionBy === undefined ? [] : (Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy]);
+			const orderBy = spec.orderBy === undefined ? [] : (Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy]);
+			const clauses: SQL[] = [];
+			if (partitionBy.length) clauses.push(sql`partition by ${sql.join(partitionBy, sql`, `)}`);
+			if (orderBy.length) clauses.push(sql`order by ${sql.join(orderBy, sql`, `)}`);
+			if (spec.frame) clauses.push(spec.frame.getSQL());
+			return sql`${expression} over (${sql.join(clauses, sql` `)})`;
+		},
+	});
+}
+
+function positiveInteger(name: 'ntile' | 'nthValue', value: number): void {
+	if (!Number.isInteger(value) || value <= 0) throw new Error(`${name}() requires a positive integer; received ${value}`);
+}
+
+function positional(name: string, args: unknown[]): SQL<unknown> {
+	return sql.raw(`${name}(${args.map((arg) => typeof arg === 'number' ? String(arg) : '').join(', ')})`);
+}
