+import { expect, test } from 'vitest';
+
+import { PgDialect, pgTable, serial } from '~/pg-core';
+import { PgSelectBuilder } from '~/pg-core/query-builders/select.ts';
+import {
+	currentRow,
+	following,
+	lag,
+	ntile,
+	preceding,
+	range,
+	rank,
+	rows,
+	windowCount,
+	windowSum,
+} from '~/sql';
+
+const users = pgTable('users', { id: serial('id') });
+const dialect = new PgDialect();
+
+test('window helpers render inline specifications and never bind positional arguments', () => {
+	const query = dialect.sqlToQuery(windowSum(users.id).over({
+		partitionBy: users.id,
+		orderBy: users.id,
+		frame: rows({ from: preceding(0), to: currentRow }),
+	}));
+	expect(query).toEqual({ sql: 'sum("users"."id") over (partition by "users"."id" order by "users"."id" rows between 0 preceding and current row)', params: [] });
+	expect(dialect.sqlToQuery(ntile(2).over()).params).toEqual([]);
+	expect(dialect.sqlToQuery(lag(users.id, 0, 0).over()).params).toEqual([0]);
+	expect(dialect.sqlToQuery(windowCount().over()).sql).toBe('count(*) over ()');
+	expect(dialect.sqlToQuery(rank().over('rank_window')).sql).toBe('rank() over "rank_window"');
+});
+
+test('named windows are emitted before order by', () => {
+	const query = new PgSelectBuilder({ fields: { id: users.id }, session: undefined, dialect })
+		.from(users)
+		.window('rank_window', { orderBy: users.id, frame: range({ from: currentRow, to: following(1) }) })
+		.orderBy(users.id);
+	expect(dialect.sqlToQuery(query.getSQL()).sql).toBe('select "id" from "users" window "rank_window" as (order by "users"."id" range between current row and 1 following) order by "users"."id"');
+});
+
+test('window validation reports invalid input', () => {
+	expect(() => ntile(0)).toThrow('ntile');
+	expect(() => preceding(-1)).toThrow('preceding');
+	expect(() => rows({ from: currentRow, to: preceding(1) })).toThrow('from');
+	expect(() => new PgSelectBuilder({ fields: { id: users.id }, session: undefined, dialect }).from(users).window('', {})).toThrow('non-empty');
+	expect(() => new PgSelectBuilder({ fields: { id: users.id }, session: undefined, dialect }).from(users).window(' ', {})).toThrow('whitespace');
+});
